/**
 * Running, rendering and exporting reports. Reports are rendered as CSV (UTF-8 with a byte-order mark for Excel),
 * Excel workbooks or PDF documents bearing the crest. Every export is recorded with its filters and row count, and
 * sensitive reports are flagged in the audit trail. Queued exports are generated by the worker with the requesting
 * user's current permissions, not those they had when they asked.
 *
 * @author Kwasi Adabo Boakye
 */

import { stringify } from 'csv-stringify/sync';
import ExcelJS from 'exceljs';
import PDFDocument from 'pdfkit';
import { models } from '../../database/models/index.js';
import { storage, buildKey } from '../../services/storage/index.js';
import { audit } from '../../services/audit.service.js';
import { enqueue } from '../../services/queue.service.js';
import { notifyUsers } from '../../services/notification.service.js';
import { loadPrincipal } from '../../middleware/auth.js';
import { forbidden, notFound } from '../../utils/errors.js';
import { hasPerm } from '../../services/accessPolicy.service.js';
import { REPORTS } from './catalog.js';
import { csvSafe } from '../../services/spreadsheet.service.js';
import { BRAND, stampCrest } from '../../services/branding.js';

export const INLINE_ROW_LIMIT = 5000;
// PDF exports are for reading, not data exchange; longer reports are truncated and point to CSV or Excel.
const PDF_ROW_LIMIT = 5000;

/**
 * Formats a cell value for CSV or PDF output: dates as ISO strings and missing values as empty text.
 *
 * @param {*} v The value.
 * @returns {*}
 */
const fmt = (v) => (v instanceof Date ? v.toISOString() : v === null || v === undefined ? '' : v);

/**
 * Lists the reports the user may run, with their group, title, sensitivity and columns.
 *
 * @param {object} user Authenticated principal.
 * @returns {object[]}
 */
export function available(user) {
  return Object.entries(REPORTS)
    .filter(([, r]) => hasPerm(user, r.perm))
    .map(([key, r]) => ({ key, title: r.title, group: r.group, sensitive: Boolean(r.sensitive), columns: r.columns }));
}

/**
 * Runs a report for the user after checking its permission.
 *
 * @param {string} key Report key.
 * @param {object} filters Report filters, such as a date range.
 * @param {object} user Authenticated principal.
 * @returns {Promise<{ report: object, rows: object[] }>}
 * @throws {AppError} 404 for an unknown report, 403 without the report's permission.
 */
export async function runReport(key, filters, user) {
  const report = REPORTS[key];
  if (!report) throw notFound('Report');
  if (!hasPerm(user, report.perm)) throw forbidden();
  const rows = await report.run(filters, user);
  return { report, rows };
}

/**
 * Renders report rows in the requested format. PDF output shows at most `PDF_ROW_LIMIT` rows and says when it has
 * been truncated.
 *
 * @param {object} report Report definition.
 * @param {object[]} rows Report rows.
 * @param {'csv'|'xlsx'|'pdf'} format Output format.
 * @param {{ from?: string, to?: string }} filters Filters, shown in the PDF heading.
 * @returns {Promise<{ buffer: Buffer, contentType: string, ext: string }>}
 */
export async function render(report, rows, format, filters) {
  if (format === 'csv') {
    return {
      buffer: Buffer.from(
        `\uFEFF${stringify(
          rows.map((r) => Object.fromEntries(report.columns.map((c) => [c.label, csvSafe(fmt(r[c.key]))]))),
          { header: true },
        )}`,
      ),
      contentType: 'text/csv; charset=utf-8',
      ext: 'csv',
    };
  }
  if (format === 'xlsx') {
    const wb = new ExcelJS.Workbook();
    wb.creator = 'UG-ARMS';
    const ws = wb.addWorksheet(report.title.slice(0, 31));
    ws.columns = report.columns.map((c) => ({
      header: c.label,
      key: c.key,
      width: Math.min(60, Math.max(12, c.label.length + 4)),
    }));
    ws.getRow(1).font = { bold: true };
    for (const r of rows)
      ws.addRow(
        Object.fromEntries(
          report.columns.map((c) => [c.key, r[c.key] instanceof Date ? r[c.key] : (r[c.key] ?? null)]),
        ),
      );
    return {
      buffer: Buffer.from(await wb.xlsx.writeBuffer()),
      contentType: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
      ext: 'xlsx',
    };
  }
  const doc = new PDFDocument({ size: 'A4', layout: report.columns.length > 4 ? 'landscape' : 'portrait', margin: 36 });
  const chunks = [];
  doc.on('data', (c) => chunks.push(c));
  const done = new Promise((r) => doc.on('end', r));
  stampCrest(doc, 40);
  doc.fillColor(BRAND.indigo).fontSize(9).text('UNIVERSITY OF GHANA ARCHIVES · UG-ARMS');
  doc.fillColor('#111').fontSize(16).text(report.title);
  doc
    .fillColor('#555')
    .fontSize(8)
    .text(
      `Generated ${new Date().toISOString()}${filters.from || filters.to ? ` · Period ${filters.from || '…'} to ${filters.to || '…'}` : ''} · ${rows.length} row(s)`,
    );
  doc.moveDown();
  const width = (doc.page.width - 72) / report.columns.length;

  /**
   * Writes the column headings at the current position of the PDF page; called again at the top of each new page.
   */
  const header = () => {
    const y = doc.y;
    report.columns.forEach((c, i) =>
      doc
        .fillColor(BRAND.indigo)
        .fontSize(8)
        .text(c.label, 36 + i * width, y, { width: width - 4 }),
    );
    doc.moveDown(0.6);
  };
  header();
  for (const r of rows.slice(0, PDF_ROW_LIMIT)) {
    if (doc.y > doc.page.height - 60) {
      doc.addPage();
      header();
    }
    const y = doc.y;
    let maxY = y;
    report.columns.forEach((c, i) => {
      doc
        .fillColor('#111')
        .fontSize(7.5)
        .text(String(fmt(r[c.key])).slice(0, 200), 36 + i * width, y, { width: width - 4 });
      maxY = Math.max(maxY, doc.y);
    });
    doc.y = maxY + 2;
  }
  if (rows.length > PDF_ROW_LIMIT)
    doc
      .fillColor('#a00')
      .fontSize(8)
      .text(
        `Truncated: PDF shows the first ${PDF_ROW_LIMIT} of ${rows.length} rows. Use CSV or Excel for the full data.`,
      );
  doc.end();
  await done;
  return { buffer: Buffer.concat(chunks), contentType: 'application/pdf', ext: 'pdf' };
}

/**
 * Records an export that was produced immediately, and audits it with its filters and row count.
 *
 * @param {string} key Report key.
 * @param {string} format Output format.
 * @param {object} filters Report filters.
 * @param {object} user Authenticated principal.
 * @param {{ rowCount: number, status?: string, storageKey?: string, filename?: string }} details Outcome of the
 *   export.
 * @returns {Promise<object>} The export record.
 */
export async function recordExport(
  key,
  format,
  filters,
  user,
  { rowCount, status = 'succeeded', storageKey, filename },
) {
  const report = REPORTS[key];
  const job = await models.ExportJob.create({
    reportType: key,
    format,
    filters,
    status,
    isSensitive: Boolean(report.sensitive),
    rowCount,
    storageKey,
    filename,
    requestedById: user.id,
    completedAt: status === 'succeeded' ? new Date() : null,
    expiresAt: new Date(Date.now() + 7 * 86400_000),
  });
  await audit({
    action: 'report.export',
    resourceType: 'ExportJob',
    resourceId: job.id,
    metadata: { report: key, format, filters, rowCount },
    sensitive: Boolean(report.sensitive),
    actor: user,
  });
  return job;
}

/**
 * Queues a large export for the worker and audits the request.
 *
 * @param {string} key Report key.
 * @param {string} format Output format.
 * @param {object} filters Report filters.
 * @param {object} user Authenticated principal.
 * @returns {Promise<object>} The queued export record.
 */
export async function queueExport(key, format, filters, user) {
  const job = await models.ExportJob.create({
    reportType: key,
    format,
    filters,
    status: 'queued',
    isSensitive: Boolean(REPORTS[key].sensitive),
    requestedById: user.id,
    expiresAt: new Date(Date.now() + 7 * 86400_000),
  });
  await audit({
    action: 'report.export_queued',
    resourceType: 'ExportJob',
    resourceId: job.id,
    metadata: { report: key, format, filters },
    sensitive: Boolean(REPORTS[key].sensitive),
  });
  await enqueue(
    'reports',
    'report.generate',
    { exportJobId: job.id },
    { entityType: 'ExportJob', entityId: job.id, requestedById: user.id },
  );
  return job;
}

/**
 * Background job: produces a queued export as the requesting user, stores the file and notifies the user in the
 * application. The export fails if the user is no longer active or has lost the report's permission.
 *
 * @param {string} exportJobId Identifier of the export record.
 * @returns {Promise<{ rows: number }|{ skipped: true }>}
 */
export async function generateQueued(exportJobId) {
  const job = await models.ExportJob.findByPk(exportJobId);
  if (!job || job.status !== 'queued') return { skipped: true };
  await job.update({ status: 'running' });
  try {
    const user = await loadPrincipal(job.requestedById);
    if (!user || user.status !== 'active') throw new Error('Requesting user is no longer active');
    const { report, rows } = await runReport(job.reportType, job.filters, user);
    const out = await render(report, rows, job.format, job.filters);
    const filename = `${job.reportType}-${new Date().toISOString().slice(0, 10)}.${out.ext}`;
    const key = buildKey('exports', filename);
    await storage.put(key, out.buffer, { contentType: out.contentType });
    await job.update({
      status: 'succeeded',
      rowCount: rows.length,
      storageKey: key,
      filename,
      completedAt: new Date(),
    });
    await notifyUsers([job.requestedById], {
      eventType: 'export.ready',
      title: `Report ready: ${report.title}`,
      body: `${rows.length} row(s).`,
      link: '/admin/reports?tab=exports',
      email: false,
    });
    return { rows: rows.length };
  } catch (err) {
    await job.update({ status: 'failed', error: err.message.slice(0, 4000) });
    throw err;
  }
}
